package cf_math_pkg;

  // return number of bits needed to represent `value` (like clog2, but exact)
  function automatic integer idx_width(integer value);
    value = value - 1;
    for (idx_width = 0; value > 0; idx_width = idx_width + 1) begin
      value = value >> 1;
    end
    if (idx_width == 0) idx_width = 1;
  endfunction

endpackage

